$src="_referencias_internas\pitch\pitch.html"; $t=[IO.File]::ReadAllText($src,[Text.UTF8Encoding]::new($false));
$css=[regex]::Match($t,'(?s)<style>(.*?)</style>').Groups[1].Value
$css=$css -replace '(?m)^\s*@page[^\n]*\n','' -replace '(?s)html, body \{[^}]*\}','' -replace '(?s)\n\s*body \{ font-family[^}]*\}',"`n"
$i=$t.IndexOf('<!-- 0 Capa -->'); $j=$t.IndexOf('<script>'); $corpo=$t.Substring($i,$j-$i)
$corpo=[regex]::Replace($corpo,'(?s)(<section class="[^"]+">.*?</section>)','<div class="quadro"><div class="escala">$1</div></div>')
$script=[regex]::Match($t,'(?s)<script>(.*?)</script>').Groups[1].Value
$page=@"
<title>Pitch Desbravadores</title>
<meta name="claude:viewport-fit-sides" content="cover">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@100;200;300;400;600;700&display=swap" rel="stylesheet">
<style>
  /* Página escura de propósito: os slides alternam claro e escuro, e o fundo neutro escuro emoldura os dois. */
  :root { --fundo: #0b0b0c; --texto: #e8e6e7; --apagado: #8d8a8c; --magenta: #DD245D; color-scheme: dark; }
  body { margin: 0; background: var(--fundo); color: var(--texto); font-family: "Inter", "Segoe UI", system-ui, sans-serif; }
  .pagina { max-width: 1280px; margin-inline: auto; padding-block: 24px 48px; padding-left: max(16px, env(safe-area-inset-left, 0px)); padding-right: max(16px, env(safe-area-inset-right, 0px)); display: grid; gap: 20px; }
  .topo { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 6px 16px; align-items: baseline; font-size: 14px; color: var(--apagado); }
  .topo b { color: var(--texto); font-weight: 600; letter-spacing: .02em; }
  .topo span { font-variant-numeric: tabular-nums; }
  .quadro { position: relative; width: 100%; aspect-ratio: 16 / 9; max-width: 100%; overflow: hidden; border-radius: 6px; }
  .escala { position: absolute; top: 0; left: 0; width: 1280px; height: 720px; transform-origin: 0 0; transform: scale(var(--s, 1)); }
  .rodape { font-size: 13px; color: var(--apagado); line-height: 1.6; max-width: 65ch; }
  /* estilos dos slides, iguais aos do PDF */
$css
</style>

<div class="pagina">
  <div class="topo"><b>Desbravadores · Fechamento Tarvo</b><span>Pitch de 10 minutos · setembro/2026</span></div>
$corpo
  <p class="rodape">Números de setembro/2026, conferidos contra a saída do repositório em 17/10/2026. Pedro Berlato, Antonio Miguel e Erick Tamura.</p>
</div>

<script>
$script
  function ajustar() { document.querySelectorAll(".quadro").forEach(q => q.style.setProperty("--s", q.clientWidth / 1280)); }
  ajustar(); addEventListener("resize", ajustar);
  if (document.fonts) document.fonts.ready.then(ajustar);
</script>
"@
[IO.File]::WriteAllText("$PWD\_referencias_internas\pitch\pitch_link.html",$page,[Text.UTF8Encoding]::new($false)); "quadros: " + ([regex]::Matches($page,'class="quadro"')).Count; "tamanho KB: " + [math]::Round($page.Length/1024)

